import * as THREE from 'three';
import type { Wall, Point } from './types';
import { getCurvedWallGeometry } from './curvedWallGeometry';

const EPS = 0.15;

// ✅ سماكة بروز المرد عن حافة الجدار (4 سم)
const SLAB_BORDER_PROTRUSION = 0.04;

// ============================================================
// ✅ تقسيم الجدار إلى قطع
// ============================================================
function getWallSegments(w: Wall): { a: Point; b: Point }[] {
  if (!w.curveRadius) {
      return [{ a: { ...w.start }, b: { ...w.end } }];
        }

          const geo = getCurvedWallGeometry(w);
            if (!geo) return [{ a: { ...w.start }, b: { ...w.end } }];

              const SEGMENTS = 10;
                const span = geo.anticlockwise
                    ? geo.startAngle - geo.endAngle
                        : geo.endAngle - geo.startAngle;
                          const dir = geo.anticlockwise ? -1 : 1;

                            // ✅ استخدام الحافة الخارجية للجدار المنحني
                              const R = geo.outerRadius;

                                const segs: { a: Point; b: Point }[] = [];
                                  let prev: Point = { ...w.start };

                                    for (let i = 1; i < SEGMENTS; i++) {
                                        const angle = geo.startAngle + dir * span * (i / SEGMENTS);
                                            const pt: Point = {
                                                  x: geo.center.x + Math.cos(angle) * R,
                                                        y: geo.center.y + Math.sin(angle) * R,
                                                            };
                                                                segs.push({ a: prev, b: pt });
                                                                    prev = pt;
                                                                      }
                                                                        segs.push({ a: prev, b: { ...w.end } });
                                                                          return segs;
                                                                          }

                                                                          // ============================================================
                                                                          // ✅ ترتيب القطاعات في حلقات
                                                                          // ============================================================
                                                                          function orderSegmentsIntoLoops(
                                                                            segments: { a: Point; b: Point }[],
                                                                            ): Point[][] {
                                                                              const loops: Point[][] = [];
                                                                                const used = new Set<number>();

                                                                                  while (used.size < segments.length) {
                                                                                      let startIdx = -1;
                                                                                          for (let i = 0; i < segments.length; i++) {
                                                                                                if (!used.has(i)) { startIdx = i; break; }
                                                                                                    }
                                                                                                        if (startIdx < 0) break;

                                                                                                            const loop: Point[] = [];
                                                                                                                let currentIdx = startIdx;
                                                                                                                    let currentPoint = segments[startIdx].a;
                                                                                                                        loop.push({ ...currentPoint });

                                                                                                                            let safety = 0;
                                                                                                                                while (safety++ < segments.length + 2) {
                                                                                                                                      used.add(currentIdx);
                                                                                                                                            const seg = segments[currentIdx];
                                                                                                                                                  const isBEnd =
                                                                                                                                                          Math.hypot(seg.b.x - currentPoint.x, seg.b.y - currentPoint.y) < EPS;
                                                                                                                                                                const nextPoint = isBEnd ? seg.a : seg.b;

                                                                                                                                                                      if (
                                                                                                                                                                              loop.length > 1 &&
                                                                                                                                                                                      Math.hypot(nextPoint.x - loop[0].x, nextPoint.y - loop[0].y) < EPS
                                                                                                                                                                                            ) {
                                                                                                                                                                                                    break;
                                                                                                                                                                                                          }
                                                                                                                                                                                                                loop.push({ ...nextPoint });
                                                                                                                                                                                                                      currentPoint = nextPoint;

                                                                                                                                                                                                                            let found = -1;
                                                                                                                                                                                                                                  for (let i = 0; i < segments.length; i++) {
                                                                                                                                                                                                                                          if (used.has(i)) continue;
                                                                                                                                                                                                                                                  const s = segments[i];
                                                                                                                                                                                                                                                          if (
                                                                                                                                                                                                                                                                    Math.hypot(s.a.x - currentPoint.x, s.a.y - currentPoint.y) < EPS ||
                                                                                                                                                                                                                                                                              Math.hypot(s.b.x - currentPoint.x, s.b.y - currentPoint.y) < EPS
                                                                                                                                                                                                                                                                                      ) {
                                                                                                                                                                                                                                                                                                found = i;
                                                                                                                                                                                                                                                                                                          break;
                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                              if (found < 0) break;
                                                                                                                                                                                                                                                                                                                                    currentIdx = found;
                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                            if (loop.length >= 3) loops.push(loop);
                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                return loops;
                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                // ============================================================
                                                                                                                                                                                                                                                                                                                                                // ✅ مساحة موقّعة + CCW
                                                                                                                                                                                                                                                                                                                                                // ============================================================
                                                                                                                                                                                                                                                                                                                                                function signedArea(polygon: Point[]): number {
                                                                                                                                                                                                                                                                                                                                                  let area = 0;
                                                                                                                                                                                                                                                                                                                                                    for (let i = 0; i < polygon.length; i++) {
                                                                                                                                                                                                                                                                                                                                                        const j = (i + 1) % polygon.length;
                                                                                                                                                                                                                                                                                                                                                            area += polygon[i].x * polygon[j].y - polygon[j].x * polygon[i].y;
                                                                                                                                                                                                                                                                                                                                                              }
                                                                                                                                                                                                                                                                                                                                                                return area / 2;
                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                function ensureCCW(polygon: Point[]): Point[] {
                                                                                                                                                                                                                                                                                                                                                                  return signedArea(polygon) < 0 ? [...polygon].reverse() : polygon;
                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                  export function polygonCentroid(polygon: Point[]): Point {
                                                                                                                                                                                                                                                                                                                                                                    if (polygon.length === 0) return { x: 0, y: 0 };
                                                                                                                                                                                                                                                                                                                                                                      let sx = 0, sy = 0;
                                                                                                                                                                                                                                                                                                                                                                        polygon.forEach(p => { sx += p.x; sy += p.y; });
                                                                                                                                                                                                                                                                                                                                                                          return { x: sx / polygon.length, y: sy / polygon.length };
                                                                                                                                                                                                                                                                                                                                                                          }

                                                                                                                                                                                                                                                                                                                                                                          // ============================================================
                                                                                                                                                                                                                                                                                                                                                                          // ✅ إزاحة المضلّع للخارج (radial)
                                                                                                                                                                                                                                                                                                                                                                          // ============================================================
                                                                                                                                                                                                                                                                                                                                                                          function offsetPolygonOutward(polygon: Point[], distance: number): Point[] {
                                                                                                                                                                                                                                                                                                                                                                            if (polygon.length < 3) return polygon;
                                                                                                                                                                                                                                                                                                                                                                              const c = polygonCentroid(polygon);
                                                                                                                                                                                                                                                                                                                                                                                return polygon.map(p => {
                                                                                                                                                                                                                                                                                                                                                                                    const dx = p.x - c.x;
                                                                                                                                                                                                                                                                                                                                                                                        const dy = p.y - c.y;
                                                                                                                                                                                                                                                                                                                                                                                            const len = Math.hypot(dx, dy) || 1;
                                                                                                                                                                                                                                                                                                                                                                                                return {
                                                                                                                                                                                                                                                                                                                                                                                                      x: p.x + (dx / len) * distance,
                                                                                                                                                                                                                                                                                                                                                                                                            y: p.y + (dy / len) * distance,
                                                                                                                                                                                                                                                                                                                                                                                                                };
                                                                                                                                                                                                                                                                                                                                                                                                                  });
                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                  // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                  // ✅ Fallback: bbox
                                                                                                                                                                                                                                                                                                                                                                                                                  // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                  function getBBoxPolygon(walls: Wall[]): Point[] | null {
                                                                                                                                                                                                                                                                                                                                                                                                                    if (walls.length === 0) return null;

                                                                                                                                                                                                                                                                                                                                                                                                                      let minX = Infinity, maxX = -Infinity;
                                                                                                                                                                                                                                                                                                                                                                                                                        let minY = Infinity, maxY = -Infinity;
                                                                                                                                                                                                                                                                                                                                                                                                                          let maxTh = 0;

                                                                                                                                                                                                                                                                                                                                                                                                                            walls.forEach(w => {
                                                                                                                                                                                                                                                                                                                                                                                                                                minX = Math.min(minX, w.start.x, w.end.x);
                                                                                                                                                                                                                                                                                                                                                                                                                                    maxX = Math.max(maxX, w.start.x, w.end.x);
                                                                                                                                                                                                                                                                                                                                                                                                                                        minY = Math.min(minY, w.start.y, w.end.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                            maxY = Math.max(maxY, w.start.y, w.end.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                maxTh = Math.max(maxTh, w.thickness);
                                                                                                                                                                                                                                                                                                                                                                                                                                                  });

                                                                                                                                                                                                                                                                                                                                                                                                                                                    const margin = maxTh / 2;

                                                                                                                                                                                                                                                                                                                                                                                                                                                      return [
                                                                                                                                                                                                                                                                                                                                                                                                                                                          { x: minX - margin, y: minY - margin },
                                                                                                                                                                                                                                                                                                                                                                                                                                                              { x: maxX + margin, y: minY - margin },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  { x: maxX + margin, y: maxY + margin },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      { x: minX - margin, y: maxY + margin },
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        export interface FootprintResult {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          polygon: Point[];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            loops: Point[][];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              valid: boolean;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // ✅ الدالة الرئيسية
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              export function extractBuildingFootprint(walls: Wall[]): FootprintResult {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const exteriorWalls = walls.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    w => w.type === 'exterior' && (w.kind === undefined || w.kind === 'wall'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (exteriorWalls.length === 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return { polygon: [], loops: [], valid: false };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const segments: { a: Point; b: Point }[] = [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  for (const w of exteriorWalls) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      segments.push(...getWallSegments(w));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const loops = orderSegmentsIntoLoops(segments);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (loops.length > 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                let largest = loops[0];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    let largestArea = Math.abs(signedArea(largest));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        for (let i = 1; i < loops.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const area = Math.abs(signedArea(loops[i]));
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (area > largestArea) { largestArea = area; largest = loops[i]; }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (largest.length >= 3 && largestArea > 0.5) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const ccwLargest = ensureCCW(largest);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // ✅ الإزاحة 4 سم فقط (سماكة المرد)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const expanded = offsetPolygonOutward(ccwLargest, SLAB_BORDER_PROTRUSION);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            polygon: ensureCCW(expanded),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    loops,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            valid: true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const bboxPoly = getBBoxPolygon(exteriorWalls);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (bboxPoly) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return { polygon: ensureCCW(bboxPoly), loops: [], valid: true };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return { polygon: [], loops: [], valid: false };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ✅ polygon → THREE.Shape
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    export function polygonToShape(polygon: Point[]): THREE.Shape | null {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if (polygon.length < 3) return null;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const shape = new THREE.Shape();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          shape.moveTo(polygon[0].x, polygon[0].y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            for (let i = 1; i < polygon.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                shape.lineTo(polygon[i].x, polygon[i].y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    shape.closePath();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return shape;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ✅ معلومات الحواف
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      // ============================================================
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      export interface EdgeInfo {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        midX: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          midZ: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            angle: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              len: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                outX: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  outZ: number;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  export function getEdgeInfos(polygon: Point[]): EdgeInfo[] {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (polygon.length < 3) return [];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const centroid = polygonCentroid(polygon);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const edges: EdgeInfo[] = [];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          for (let i = 0; i < polygon.length; i++) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const p1 = polygon[i];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const p2 = polygon[(i + 1) % polygon.length];
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const dx = p2.x - p1.x;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const dz = p2.y - p1.y;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const len = Math.hypot(dx, dz);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if (len < 0.01) continue;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const midX = (p1.x + p2.x) / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const midZ = (p1.y + p2.y) / 2;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const angle = Math.atan2(-dz, dx);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const n1 = { x: dz / len, y: -dx / len };
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const n2 = { x: -dz / len, y: dx / len };

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const test1X = midX + n1.x * 0.1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const test1Z = midZ + n1.y * 0.1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const test2X = midX + n2.x * 0.1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      const test2Z = midZ + n2.y * 0.1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          const d1 = Math.hypot(test1X - centroid.x, test1Z - centroid.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              const d2 = Math.hypot(test2X - centroid.x, test2Z - centroid.y);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  const outward = d1 > d2 ? n1 : n2;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      edges.push({ midX, midZ, angle, len, outX: outward.x, outZ: outward.y });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          return edges;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          }